sealed record RouteRule(string Match, string Destination);
sealed class RoutingOptions { public List<RouteRule> Rules { get; set; } = new(); }

public sealed class Router(IOptionsMonitor<RoutingOptions> monitor)
{
    public Task RouteAsync(Message m, CancellationToken ct)
    {
        var rules = monitor.CurrentValue.Rules;            // snapshot per message
        var rule  = rules.FirstOrDefault(r => r.Match == m.Key);
        return rule is null ? _deadLetter.SendAsync(m, ct) : Dispatch(rule.Destination, m, ct);
    }
}

